private let logger = Log.logger(category: "create-repository")

// MARK: - Templates

/// A license Create can add.
public struct RepositoryLicense: Sendable, Hashable, Identifiable {
    /// The human-readable name.
    public let name: String
    /// Is the license featured?
    public let isFeatured: Bool
    /// The actual text of the license, with its `[year]` or `{year}` style
    /// tokens.
    public let body: String

    public init(name: String, isFeatured: Bool, body: String) {
        self.name = name
        self.isFeatured = isFeatured
        self.body = body
    }

    public var id: String {
        name
    }
}

/// The .gitignore templates and licenses Create offers: github/gitignore's
/// and choosealicense.com's.
public enum RepositoryTemplates {
    /// The names of the available gitignores, sorted.
    public static var gitIgnoreNames: [String] {
        bundledGitIgnores.map(\.name)
    }

    /// The gitignore named `name`, from `gitIgnoreNames`; nil for another
    /// name.
    public static func gitIgnoreText(named name: String) -> String? {
        bundledGitIgnores.first { JSCompat.strictEquals($0.name, name) }?.text
    }

    /// The available licenses: the featured ones first, then the others,
    /// each by name.
    public static var licenses: [RepositoryLicense] {
        featuredLicenses + otherLicenses
    }

    /// The licenses listed before the divider.
    public static var featuredLicenses: [RepositoryLicense] {
        bundledLicenses.filter(\.isFeatured)
    }

    /// The licenses listed after the divider.
    public static var otherLicenses: [RepositoryLicense] {
        bundledLicenses.filter { !$0.isFeatured }
    }

    /// The license named `name`, if there's one.
    public static func license(named name: String) -> RepositoryLicense? {
        bundledLicenses.first { JSCompat.strictEquals($0.name, name) }
    }
}

/// What a license's tokens are filled with.
public struct LicenseFields: Sendable, Equatable {
    public var fullname: String
    public var email: String
    public var project: String
    public var description: String
    public var year: String

    public init(fullname: String, email: String, project: String, description: String, year: String) {
        self.fullname = fullname
        self.email = email
        self.project = project
        self.description = description
        self.year = year
    }
}

/// The license's text with its tokens filled in. The templates are
/// inconsistent: sometimes they use `[token]` and sometimes `{token}`, so
/// both are replaced, token by token. Values are inserted as they are:
/// `$&` and the like in them aren't read as patterns.
public func licenseText(_ license: RepositoryLicense, _ fields: LicenseFields) -> String {
    let tokens: [(String, String)] = [
        ("fullname", fields.fullname),
        ("email", fields.email),
        ("project", fields.project),
        ("description", fields.description),
        ("year", fields.year),
    ]
    var body = license.body
    for (token, value) in tokens {
        body = body.replacingOccurrences(of: "[\(token)]", with: "{\(token)}")
        body = body.replacingOccurrences(of: "{\(token)}", with: value)
    }
    return body
}

/// Sanitize a proposed repository name by replacing illegal characters:
/// emoji (U+1F300 to U+1F3FF, U+1F400 to U+1F64F, U+1F680 to U+1F6FF)
/// become one `-` each, then every UTF-16 code unit that isn't an ASCII
/// letter, digit, `_`, `.` or `-` becomes `-`, as JavaScript's
/// `/[^\w.-]/g` replaces them.
public func sanitizedRepositoryName(_ name: String) -> String {
    let emojiRanges: [ClosedRange<UInt32>] = [0x1F300...0x1F3FF, 0x1F400...0x1F64F, 0x1F680...0x1F6FF]
    var result = ""
    for scalar in name.unicodeScalars {
        if emojiRanges.contains(where: { $0.contains(scalar.value) }) {
            result += "-"
            continue
        }
        switch scalar {
        case "a"..."z", "A"..."Z", "0"..."9", "_", ".", "-":
            result.unicodeScalars.append(scalar)
        default:
            // One `-` per UTF-16 code unit: two for characters outside the
            // Basic Multilingual Plane.
            result += String(repeating: "-", count: UTF16.width(scalar))
        }
    }
    return result
}

/// The README's file name.
private let defaultReadmeName = "README.md"

/// The README a new repository starts with: the name as a heading, then
/// the description.
func defaultReadmeContents(_ name: String, _ description: String?) -> String {
    if let description {
        return "# \(name)\n\(description)\n"
    }
    return "# \(name)\n"
}

/// Write the default README to the repository with the given name at the
/// path.
public func writeDefaultReadme(_ path: String, _ name: String, _ description: String? = nil) async throws {
    let fullPath = POSIXPath.join(path, defaultReadmeName)
    try await writeFile(fullPath, defaultReadmeContents(name, description))
}

/// Write the .gitattributes file to the given repository.
public func writeGitAttributes(_ path: String) async throws {
    let fullPath = POSIXPath.join(path, ".gitattributes")
    let contents = "# Auto detect text files and perform LF normalization\n* text=auto\n"
    try await writeFile(fullPath, contents)
}

/// Write the license to the repository at the given path.
public func writeLicense(_ repositoryPath: String, _ license: RepositoryLicense, _ fields: LicenseFields) async throws {
    let fullPath = POSIXPath.join(repositoryPath, "LICENSE")
    try await writeFile(fullPath, licenseText(license, fields))
}

/// Write the named gitignore to the repository.
///
/// - Throws: For a name that isn't one of `RepositoryTemplates.gitIgnoreNames`.
public func writeGitIgnore(_ repositoryPath: String, _ name: String) async throws {
    let fullPath = POSIXPath.join(repositoryPath, ".gitignore")
    guard let text = RepositoryTemplates.gitIgnoreText(named: name) else {
        throw CreateRepositoryStepError("Unknown gitignore: \(name). Only names returned from getGitIgnoreNames() can be used.")
    }
    try await writeFile(fullPath, text)
}

// MARK: - The sheet's checks

/// What to create (the Create sheet's fields).
public struct CreateRepositoryRequest: Sendable, Equatable {
    /// The name typed: the folder's name (made with `basePath`), and the
    /// project's name in the README and the license.
    public var name: String
    public var description: String
    /// The folder the repository goes in.
    public var basePath: String
    /// "Initialize this repository with a README".
    public var createsReadme: Bool
    /// The .gitignore template's name (`RepositoryTemplates.gitIgnoreNames`),
    /// or nil for none.
    public var gitIgnore: String?
    /// The license's name (`RepositoryTemplates.licenses`), or nil for none.
    public var license: String?
    /// Whether `basePath` becomes the folder the next clone or create starts
    /// in. Not when the sheet was opened for a folder (Add's "create a
    /// repository here instead"): that would be the repository's own parent.
    public var remembersBasePath: Bool

    public init(
        name: String,
        description: String = "",
        basePath: String,
        createsReadme: Bool = false,
        gitIgnore: String? = nil,
        license: String? = nil,
        remembersBasePath: Bool = true
    ) {
        self.name = name
        self.description = description
        self.basePath = basePath
        self.createsReadme = createsReadme
        self.gitIgnore = gitIgnore
        self.license = license
        self.remembersBasePath = remembersBasePath
    }

    /// The repository's folder: the name joined to the base path (the name
    /// isn't changed, and a `/` in it makes folders), or nil while the base
    /// path is empty or the name blank.
    public var fullPath: String? {
        guard !basePath.isEmpty, !JSCompat.trim(name).isEmpty else {
            return nil
        }
        return POSIXPath.join(basePath, name)
    }
}

/// What's at the folder a repository would be created in (the sheet's
/// warnings).
public struct CreateRepositoryDestination: Sendable, Equatable {
    /// The folder is a repository already (its top level, or a bare one):
    /// creating is off, and the sheet offers to add it instead.
    public var isRepository: Bool
    /// The folder is inside a repository: the sheet points to submodules.
    public var isSubfolderOfRepository: Bool
    /// The folder has a README.md that "Initialize this repository with a
    /// README" would overwrite.
    public var readmeExists: Bool

    public init(isRepository: Bool = false, isSubfolderOfRepository: Bool = false, readmeExists: Bool = false) {
        self.isRepository = isRepository
        self.isSubfolderOfRepository = isSubfolderOfRepository
        self.readmeExists = readmeExists
    }
}

/// Checks the folder a repository would be created in.
///
/// A folder git considers unsafe can't be asked, so it counts as a
/// repository when it has a `.git`. A regular repository's folder is the
/// repository when it's the top level, and a subfolder otherwise. Paths
/// compare without a trailing slash: compared as typed, `name/` would make
/// a repository's own folder look like a subfolder, and creating there
/// would commit everything in it as "Initial commit".
public func checkCreateRepositoryDestination(_ fullPath: String) async -> CreateRepositoryDestination {
    let type: RepositoryType
    do {
        type = try await getRepositoryType(fullPath)
    } catch {
        logger.error("Unable to determine repository type: \(error.localizedDescription, privacy: .public)")
        type = .missing
    }

    var destination = CreateRepositoryDestination()
    switch type {
    case .missing:
        break
    case .bare:
        destination.isRepository = true
    case .unsafe:
        // If the path is considered unsafe by Git we won't be able to verify
        // that it's a repository (or worktree). So we'll fall back to this
        // naive approximation.
        destination.isRepository = await directoryExists(POSIXPath.join(fullPath, ".git"))
    case .regular(let topLevelWorkingDirectory, _):
        // If the path is a regular repository, we'll check if the top level.
        // If it isn't, the path is a subfolder of the repository and a user
        // may want to make it into a repository.
        destination.isRepository = samePath(topLevelWorkingDirectory, fullPath)
        destination.isSubfolderOfRepository = !destination.isRepository
    }
    destination.readmeExists = await pathExists(POSIXPath.join(fullPath, defaultReadmeName))
    return destination
}

/// Whether two paths name the same folder: normalized, without a trailing
/// slash.
private func samePath(_ x: String, _ y: String) -> Bool {
    func folder(_ path: String) -> String {
        let normalized = POSIXPath.normalize(path)
        return normalized.count > 1 && JSCompat.endsWith(normalized, "/") ? String(normalized.dropLast()) : normalized
    }
    return JSCompat.strictEquals(folder(x), folder(y))
}

// MARK: - Creating

/// What creating a repository did.
public struct CreateRepositoryResult: Sendable, Equatable {
    /// The repository, added to the list and selected.
    public let repositoryID: RepositoryID
    /// The steps that failed once the repository existed (README,
    /// .gitignore, description, LICENSE, .gitattributes, the initial
    /// commit), in order. The rest went on; the sheet shows them once it
    /// closes.
    public let failures: [OperationError]

    public init(repositoryID: RepositoryID, failures: [OperationError]) {
        self.repositoryID = repositoryID
        self.failures = failures
    }
}

/// The message when the folder can't be made.
let createRepositoryDirectoryMessage =
    "Couldn't create a folder at this path. You may not have permission to create folders here."

extension AppModel {
    /// Creates a repository:
    ///
    /// 1. makes the folder (and those above it), and runs `git init` there
    ///    with the default branch for new repositories;
    /// 2. adds the repository to the list (`addRepositories`);
    /// 3. writes the README, the .gitignore template, the description
    ///    (`.git/description`), the license (with the repository's author),
    ///    and a .gitattributes when there's none; a step that fails is
    ///    reported and the rest go on;
    /// 4. commits every file in the folder as "Initial commit", unless it's
    ///    empty;
    /// 5. remembers the base path for the next clone or create (unless the
    ///    sheet was opened for a folder), and selects the repository.
    ///
    /// Steps 3 and 4 run as an operation in the repository's local lane;
    /// it returns after the refresh.
    ///
    /// - Returns: The repository, and the steps of 3 and 4 that failed.
    /// - Throws: `.precondition` without a name or base path, and for a
    ///   folder that is a repository already (checked again here; the sheet
    ///   offers to add it); `.fileSystem` with
    ///   `createRepositoryDirectoryMessage` when the folder can't be made;
    ///   git's error when `git init` or reading the new repository's status
    ///   fails ("Couldn't Create Repository").
    public func createRepository(_ request: CreateRepositoryRequest) async throws(OperationError) -> CreateRepositoryResult {
        guard let fullPath = request.fullPath else {
            throw createFailure(.precondition("Enter a name and a folder for the repository."))
        }
        // A relative path would resolve against this process's folder, not
        // the one the user sees. The sheet always gives a full path.
        guard POSIXPath.isAbsolute(fullPath) else {
            throw createFailure(.precondition("Choose the folder for the repository by its full path."))
        }
        if await checkCreateRepositoryDestination(fullPath).isRepository {
            throw createFailure(.precondition("\(fullPath) is already a Git repository."))
        }

        do {
            try await makeDirectory(fullPath)
        } catch {
            logger.error("createRepository: the directory at \(fullPath, privacy: .private) is not valid: \(error.localizedDescription, privacy: .public)")
            let permissionDenied = (error as? POSIXError)?.code == .EACCES
            throw createFailure(.fileSystem(permissionDenied ? createRepositoryDirectoryMessage : error.localizedDescription), underlying: error)
        }

        do {
            try await environment.withRuntimes {
                try await initGitRepository(fullPath)
            }
        } catch {
            logger.error("createRepository: unable to initialize a Git repository at \(fullPath, privacy: .private)")
            throw await classifyCreateFailure(error)
        }

        let added = try await addRepositories([fullPath])
        guard let id = added.repositories.first else {
            throw createFailure(.precondition(added.invalidPathsMessage ?? "\(fullPath) isn't a Git repository."))
        }
        if added.existing.contains(id), record(id)?.isMissing == true {
            // A missing repository was listed at this folder: it's back.
            await checkRepositoryAgain(id)
        }
        guard let repository = repository(id), let record = record(id), !record.isMissing else {
            throw createFailure(.precondition("\(fullPath) isn't a Git repository."))
        }

        let year = String(Calendar(identifier: .gregorian).component(.year, from: environment.scheduler.now))
        let descriptor = OperationDescriptor(kind: .createRepository, gitContext: .createRepository, refreshAfter: .full)
        let failures = try await repository.perform(descriptor) { ctx -> [OperationError] in
            try await self.populateNewRepository(ctx, request: request, year: year)
        }
        await repository.awaitOperationRefresh(covering: .full)

        // Don't update the default directory when the sheet was opened for a
        // folder: the value would be the repository's own parent.
        if request.remembersBasePath {
            preferences.lastCloneLocation = request.basePath
        }
        select(.repository(id))
        return CreateRepositoryResult(repositoryID: id, failures: failures)
    }

    /// Writes the new repository's files and makes its initial commit.
    /// Failures of the files and the commit are returned; reading the status
    /// is the one that's thrown.
    private func populateNewRepository(
        _ ctx: OperationContext,
        request: CreateRepositoryRequest,
        year: String
    ) async throws -> [OperationError] {
        let repository = ctx.repository
        let path = repository.path
        var failures: [OperationError] = []

        func attempt(_ step: String, _ body: () async throws -> Void) async {
            do {
                try await body()
            } catch {
                logger.error("createRepository: unable to \(step, privacy: .public) at \(path, privacy: .private): \(error.localizedDescription, privacy: .public)")
                failures.append(await self.classifyCreateFailure(error))
            }
        }

        if request.createsReadme {
            await attempt("write README") {
                // An empty description would leave a blank second line.
                try await writeDefaultReadme(path, request.name, request.description.isEmpty ? nil : request.description)
            }
        }

        if let name = request.gitIgnore {
            await attempt("write .gitignore file") {
                try await writeGitIgnore(path, name)
            }
        }

        if !request.description.isEmpty {
            await attempt("write .git/description file") {
                try await writeGitDescription(path, request.description)
            }
        }

        if let name = request.license {
            await attempt("write LICENSE") {
                guard let license = RepositoryTemplates.license(named: name) else {
                    throw CreateRepositoryStepError("Unknown license: \(name).")
                }
                let author = try await getAuthorIdentity(repository)
                let fields = LicenseFields(
                    fullname: author?.name ?? "",
                    email: author?.email ?? "",
                    project: request.name,
                    description: "",
                    year: year
                )
                try await writeLicense(path, license, fields)
            }
        }

        await attempt("write .gitattributes") {
            if !(await pathExists(POSIXPath.join(path, ".gitattributes"))) {
                try await writeGitAttributes(path)
            }
        }

        // Reading the status is the one failure that stops: without it
        // there's nothing to commit.
        guard let status = try await getStatus(repository, includeUntracked: true, rejectOnError: true) else {
            throw CreateRepositoryStepError("Unable to read the status of the new repository.")
        }

        let files = status.workingDirectory.files
        if !files.isEmpty {
            let hooks = ctx.hooks
            await attempt("make the initial commit") {
                try await createCommit(repository, "Initial commit", files, CreateCommitOptions(
                    onHookProgress: hooks.onHookProgress,
                    onHookFailure: hooks.onHookFailure,
                    onTerminalOutputAvailable: hooks.onTerminalOutputAvailable
                ))
            }
        }
        return failures
    }

    private func createFailure(_ reason: OperationError.Reason, underlying: (any Error)? = nil) -> OperationError {
        OperationError(reason, operation: .createRepository, underlying: underlying, gitContext: .createRepository)
    }

    /// A step's error, titled "Couldn't Create Repository".
    private func classifyCreateFailure(_ error: any Error) async -> OperationError {
        await ErrorClassifier.classify(
            error,
            descriptor: OperationDescriptor(kind: .createRepository, lanes: [], gitContext: .createRepository),
            record: nil,
            context: ClassificationContext()
        )
    }
}

/// A step of creating a repository that failed without a git or file
/// system error.
private struct CreateRepositoryStepError: LocalizedError {
    let message: String

    init(_ message: String) {
        self.message = message
    }

    var errorDescription: String? {
        message
    }
}

/// Makes `path` and the folders above it, with the names' bytes as given:
/// FileManager decomposes non-ASCII names.
@concurrent
private func makeDirectory(_ path: String) async throws {
    var current = ""
    for component in JSCompat.split(path, "/") where !component.isEmpty {
        current += "/" + component
        guard mkdir(current, 0o777) != 0 else {
            continue
        }
        let code = errno
        var info = stat()
        if code == EEXIST, stat(current, &info) == 0, info.st_mode & S_IFMT == S_IFDIR {
            continue
        }
        throw POSIXError(POSIXErrorCode(rawValue: code == EEXIST ? ENOTDIR : code) ?? .EIO)
    }
}

/// Writes `text` to `path` as UTF-8, replacing what's there. The path stays a
/// string: `URL(filePath:)` decomposes non-ASCII names.
@concurrent
private func writeFile(_ path: String, _ text: String) async throws {
    try (Data(text.utf8) as NSData).write(toFile: path, options: [])
}